import{z as p,x as A,o as l,c as B,q as o,j as r,D as e,d as t,s,S as n,b as E}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"光瞳图优化","description":"","frontmatter":{"title":"光瞳图优化","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/pupil-source-map.md","filePath":"litho/pupil-source-map.md","lastUpdated":1791063341000}'),d={name:"litho/pupil-source-map.md"};function h(C,a,m,u,P,D){const i=A("Mermaid");return l(),B("div",null,[a[2]||(a[2]=o('<h1 id="光瞳图优化" tabindex="-1">光瞳图优化 <a class="header-anchor" href="#光瞳图优化" aria-label="Permalink to &quot;光瞳图优化&quot;">​</a></h1><div class="epigraph"><p>自由光源不是把瞳面调亮，而是把能量像素化地分配到能形成干涉的那些点上；花瓣图若不能被扫描仪实现，只是计算域里的最优。</p><footer>—— 对照 ASML 对 SMO 与自由成形照明的公开论述</footer></div><p><a href="/litho/smo">上一课</a>已经把 SMO 收成光源与掩模的联合逆问题：光瞳改 TCC，掩模在既定通带里修边。缺口是光源那一侧的表示。传统 RET 只在常规、环形、偶极、四极里选；自由光瞳把瞳面切成像素（或极坐标基），每个像素的强度成为优化变量。本课钉光瞳图。像差与波前如何再进协同，留给<a href="/litho/smo-plus-wavefront">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>部分相干成像里，光源上每一点对应一组倾斜照明。像素化之后，变量数从「几个 σ 和叶片角」变成几百到上千个瞳面自由度。可行集变大，二维逻辑与 SRAM 的窗口交才有机会同时活；可行集也变脏：扫描仪的柔性照明器有最小特征、能量效率、热负载和衍射光学元件的可制造性。优化若不管这些，会输出一张漂亮但照不出来的灰度图。</p><p>目标函数必须是一批关键 clips 的窗口交，而不是单条密线的对比冠军。某一像素变亮，可能抬高某一取向的 NILS，同时让正交取向的焦深崩溃。缺口因此是：在可实现光瞳上搜，而不是在任意 \\(L^2\\) 函数上搜。</p><h3 id="像素不是独立旋钮" tabindex="-1">像素不是独立旋钮 <a class="header-anchor" href="#像素不是独立旋钮" aria-label="Permalink to &quot;像素不是独立旋钮&quot;">​</a></h3><p>相邻像素通过光学传递和照明器约束耦合。把 SMO 理解成「每个像素调一个百分比」会得到高频噪声光瞳，成形效率差、对对准误差敏感。工程上要平滑、对称（或按 EUV 阴影故意不对称）、以及最小孤岛尺寸。ASML 公开的自由光源能力，指的是照明器能逼近的那类图，不是任意位图。</p><p><span class="marginnote">光瞳图的坐标是照明瞳，不是投影物镜的成像瞳。两者相关但不是同一张图。把 SMO 输出直接当成波前校正图，会把下一课的自由度提前用错。</span></p><p><span class="marginnote">直觉类比：说「像素不是独立旋钮」，就像调音台上相邻两个推子之间连着弹簧——你单推一个，旁边的会被带歪，最后出来的不是你按下去的那个组合。所以光瞳优化不能逐像素乱拨，输出的必须是平滑、成块的形状，否则机台根本还原不出来。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>典型参数化：笛卡尔像素、扇区、或 Zernike/极坐标基。优化在代表性单元、SRAM、孔与切层 clips 上跑，掩模用边碎片或粗像素，成本含 PV-band、MEEF、ILS，外加光源传输惩罚。收敛后把连续图投影到照明器可实现集合（叶片、DOE、FlexRay 一类柔性照明的公开能力），再冻结，全芯片 <a href="/litho/opc">OPC</a> 或 ILT。</p><p>EUV 上 6° 主光线让水平/垂直不对称，光瞳图常常是取向相关的自由形状，再由设计规则限制允许节距。DUV 浸没已经证明自由光源能在不改 NA 时再挖一截 \\(k_1\\)；EUV 上这一截用来换更少双重，或给随机预算留对比余量。</p><h3 id="从种子到可实现投影" tabindex="-1">从种子到可实现投影 <a class="header-anchor" href="#从种子到可实现投影" aria-label="Permalink to &quot;从种子到可实现投影&quot;">​</a></h3><p>从环形或偶极种子出发，比从白噪声瞳开始更稳，因为目标非凸。投影步骤不可省：计算最优与机台最优之间的差，要在硅上验证，不能只报优化器 loss。传输过低的光瞳会拉长扫描时间，把<a href="/litho/photon-shot-budget">光子预算</a>的剂量上限往下拉——光瞳图因此也是产能图。</p>',15)),(l(),r(n,null,{default:e(()=>[s(i,{id:"mermaid-43",class:"mermaid",graph:"flowchart%20TD%0A%20%20SEED%5B%22%E7%8E%AF%E5%BD%A2%20%2F%20%E5%81%B6%E6%9E%81%E7%A7%8D%E5%AD%90%22%5D%20--%3E%20OPT%5B%22clips%20%E4%B8%8A%E8%81%94%E5%90%88%E4%BC%98%E5%8C%96%22%5D%0A%20%20NOISE%5B%22%E7%99%BD%E5%99%AA%E5%A3%B0%E7%9E%B3%22%5D%20-.%E7%9B%AE%E6%A0%87%E9%9D%9E%E5%87%B8%E6%98%93%E5%8F%91%E6%95%A3.-%3E%20OPT%0A%20%20OPT%20--%3E%20PROJ%5B%22%E6%8A%95%E5%BD%B1%E5%88%B0%E7%85%A7%E6%98%8E%E5%99%A8%E5%8F%AF%E5%AE%9E%E7%8E%B0%E9%9B%86%22%5D%0A%20%20PROJ%20--%3E%20VER%5B%22%E7%A1%85%E4%B8%8A%E9%AA%8C%E8%AF%81%E7%AA%97%E5%8F%A3%E4%B8%8E%20MEEF%22%5D%0A%20%20VER%20--%3E%7C%E8%BE%BE%E6%A0%87%7C%20FRZ%5B%22%E5%86%BB%E7%BB%93%E5%85%89%E7%9E%B3%20%2B%20%E5%85%A8%E8%8A%AF%E7%89%87%20OPC%22%5D%0A%20%20VER%20--%3E%7C%E4%B8%8D%E8%BE%BE%E6%A0%87%7C%20SEED%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,[E("span",{class:"marginnote"},"术语翻译：「投影到可实现集合」意思是把优化器画出的理想灰度光瞳，硬压回机台真的照得出来的那批形状里——好比把分辨率无限的矢量图转成打印机实际能打的位图，细节会被取舍，但至少打得出来。跳过这一步，得到的就是「照不出来」的最优解。")],-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[t("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,"Hopkins 的 TCC 由光源与瞳函数决定。改像素即改 TCC 的谱结构，空中像算子的本征方向跟着转。掩模变量通过这个算子映射到轮廓。联合优化在「光源可行集 × 掩模可行集」上走；光源是场级全局变量，所以只能在抽样 clips 上动光瞳，不能让每一标准单元拥有自己的光瞳。",-1)),a[6]||(a[6]=E("p",null,"MEEF 把掩模误差放大。某些高对比光瞳把 MEEF 抬到掩模厂接不住。光瞳图优化必须把 MEEF 与 MRC 放进成本，否则窗口数字好看，版写不出来。",-1)),a[7]||(a[7]=E("p",null,[E("span",{class:"marginnote"},"宣传材料里的花瓣光瞳若没有对应的掩模协同和全芯片 OPC，只是照明器能力演示。评价要看冻结该光瞳之后全芯片的 PV-band，而不是 clips 上的对比度冠军。")],-1)),(l(),r(n,null,{default:e(()=>[s(i,{id:"mermaid-59",class:"mermaid",graph:"flowchart%20TD%0A%20%20PIX%5B%22%E5%85%89%E7%9E%B3%E5%83%8F%E7%B4%A0%22%5D%20--%3E%20TCC%5B%22TCC%20%2F%20%E5%B9%B2%E6%B6%89%E6%9D%A1%E4%BB%B6%22%5D%0A%20%20MSK%5B%22%E6%8E%A9%E6%A8%A1%E5%8F%98%E9%87%8F%22%5D%20--%3E%20IMG%5B%22%E7%A9%BA%E4%B8%AD%E5%83%8F%22%5D%0A%20%20TCC%20--%3E%20IMG%0A%20%20IMG%20--%3E%20COST%5B%22%E7%AA%97%E5%8F%A3%E4%BA%A4%20%2B%20MEEF%20%2B%20%E4%BC%A0%E8%BE%93%22%5D%0A%20%20COST%20--%3E%20PROJ%5B%22%E6%8A%95%E5%BD%B1%E5%88%B0%E5%8F%AF%E5%AE%9E%E7%8E%B0%E7%85%A7%E6%98%8E%22%5D%0A%20%20PROJ%20--%3E%20OPC%5B%22%E5%86%BB%E7%BB%93%E5%90%8E%E5%85%A8%E8%8A%AF%E7%89%87%20OPC%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[8]||(a[8]=o('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>光瞳图优化不增加 NA，不缩短波长。它只在现有透镜通带里重新分配能量。未抽到的热区会在量产中冒出来，通常用 OPC 补丁，而不是每周改光瞳——光源一改，所有层 OPC 重放。计算量在定规则阶段，真正的 CPU/GPU 墙仍在全芯片修正。</p><p>后课默认：自由光瞳是像素化并可投影到照明器的那张图；下一课再把投影光学的波前自由度加进去。</p><p><span class="marginnote">为什么重要：光瞳一旦改动，TCC 就变了，所有层已经标定好的 OPC 模型随之失效，必须全量重放——这是数天量级的算力开销。所以量产中宁可对个别热点打 OPC 补丁，也不轻易动光瞳；「每周微调光源」在产线上不是选项。</span></p><p><span class="marginnote">比较两张光瞳要同时报：关键图形窗口交、MEEF、照明效率、以及换成该光源后 OPC 的掩模复杂度。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>光瞳图优化把照明能量像素化，改的是干涉条件，不是总亮度。</li><li>必须投影到扫描仪可实现集合，否则最优不可照明。</li><li>光源是场级变量，只在代表性 clips 上优化再冻结。</li><li>EUV 阴影让自由光瞳取向相关；MEEF 与产率必须进成本。</li><li>出处：ASML 关于 SMO 与自由成形光源的公开方法。</li></ul>',7))])}const f=p(d,[["render",h]]);export{c as __pageData,f as default};
